                 /\ munch [(lo, bv_unsigned sp); (Fp, Fp + 232)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'
                 /\ stk asegs m' lo (bv_unsigned sp)
                 /\ rw_cells asegs m' Fp (file_cells flags bufp bufp bufp wfn bufp 0 fd mode' lbf tail))
